def count_vowels(s: str) -> int:
    vowels = set("aeiouAEIOU")
    count = 0
    for i, ch in enumerate(s):
        if ch not in vowels:
            left = i > 0 and s[i - 1] in vowels
            right = i < len(s) - 1 and s[i + 1] in vowels
            if left or right:
                count += 1
    return count
